## 📝 참고

### NetworkManager 사용 예시

1. GET 요청 (JSON 응답)
``` swift
struct User: Codable {
    let id: Int
    let name: String
}

Task {
    do {
        let user: User = try await NetworkManager.shared.request(
            url: "https://api.example.com/users/1",
            method: .GET,
            responseType: User.self
        )
        print("사용자: \(user.name)")
    } catch {
        print("에러: \(error.localizedDescription)")
    }
}
```

2. POST 요청 (JSON 바디)
``` swift
let newUser = NewUser(name: "김철수")
let jsonData = try JSONEncoder().encode(newUser)

Task {
    do {
        let created: User = try await NetworkManager.shared.request(
            url: "https://api.example.com/users",
            method: .POST,
            body: jsonData,
            responseType: User.self
        )
        print("생성됨: \(created.id)")
    } catch {
        print("에러: \(error)")
    }
}
```

3. 쿼리 파라미터 사용
``` swift
Task {
    do {
        let users: [User] = try await NetworkManager.shared.request(
            url: "https://api.example.com/users",
            method: .GET,
            parameters: ["page": "1", "search": "김철수"],
            responseType: [User].self
        )
        print("받음: \(users.count)명")
    } catch {
        print(error)
    }
}
```

4. ViewModel에서 사용 (SwiftUI / @MainActor)
``` swift
@MainActor
class UserViewModel: ObservableObject {
    @Published var user: User?

    func loadUser() {
        Task { [weak self] in
            guard let self = self else { return }
            do {
                let u: User = try await NetworkManager.shared.request(
                    url: "https://api.example.com/users/1",
                    responseType: User.self
                )
                self.user = u       // MainActor 보장
            } catch {
                print(error)
            }
        }
    }
}
```

5. 취소처리 예시
``` swift
let task = Task {
    try Task.checkCancellation()
    let user: User = try await NetworkManager.shared.request(... )
    print(user)
}

// 취소하려면
task.cancel()
```

### AlanAIService 사용 예시

1. 예시(헬스플랜 생성 (직접 반환형을 사용))
``` swift
let alanService = AlanAIService()
let planRequest = PlanRequest(planType: .routine, preferences: ["운동", "다이어트"])

Task {
    do {
        let plan = try await alanService.generateHealthPlan(planRequest)
        print("받은 플랜 제목: \(plan.title)")
        // alanService.healthPlan도 내부에서 업데이트하도록 구현해두면 SwiftUI에서 자동 반영됨
    } catch {
        print("에러: \(error)")
    }
}
```

2. 만약 generateHealthPlan이 내부에서만 @Published로 업데이트(반환값 없음)된다면 — 값 대기하기
``` swift
Task {
    // generate 호출
    Task.detached {
        try await alanService.generateHealthPlan(planRequest) // 내부에서 healthPlan 업데이트
    }

    // 업데이트된 healthPlan 받기 (첫 non-nil)
    for await maybePlan in alanService.$healthPlan.values {
        if let plan = maybePlan {
            print("업데이트된 플랜: \(plan.title)")
            break
        }
    }
}
```

3. 일반 AI 요청 (문자열 응답)
``` swift
Task {
    do {
        let response = try await alanService.requestString(prompt: "건강한 식단을 추천해주세요")
        print("AI 응답: \(response)")
    } catch {
        print("에러:", error)
    }
}
```

4. SwiftUI .task에서 호출
``` swift
struct ContentView: View {
    @StateObject private var vm = UserViewModel()

    var body: some View {
        Text(vm.user?.name ?? "로딩중...")
            .task {
                await vm.loadUserAsync()
            }
    }
}

@MainActor
class UserViewModel: ObservableObject {
    @Published var user: User?

    func loadUserAsync() async {
        do {
            let u: User = try await NetworkManager.shared.request(url: "...", responseType: User.self)
            self.user = u
        } catch {
            print(error)
        }
    }
}
```

